mapper.select:
SELECT id, matrix_id, chapter_id, topic, order_index
FROM edu.exam_matrix_rows WHERE matrix_id = #{matrixId}
ORDER BY order_index ASC, id ASC

mapper.delete:
DELETE FROM edu.exam_matrix_row_learning_outcomes mapping
WHERE mapping.exam_matrix_row_id = #{rowId}
  AND NOT EXISTS (
    SELECT 1
    FROM edu.exam_matrix_rows matrix_row
    JOIN edu.chapter_learning_outcomes chapter_outcome
      ON chapter_outcome.chapter_id = matrix_row.chapter_id
     AND chapter_outcome.learning_outcome_id = mapping.learning_outcome_id
    WHERE matrix_row.id = #{rowId}
  )

mapper.update:
UPDATE edu.exam_matrix_row_learning_outcomes
SET is_selected = FALSE
WHERE exam_matrix_row_id = #{rowId}

UPDATE edu.exam_matrix_row_learning_outcomes
SET is_selected = TRUE
WHERE exam_matrix_row_id = #{rowId}
  AND learning_outcome_id IN
  #{outcomeId}

UPDATE edu.exam_matrix_rows
SET chapter_id = #{chapterId}, topic = #{topic}, order_index = #{orderIndex}
WHERE id = #{id} AND matrix_id = #{matrixId}
